// A static, type-safe specification validated at compile-time
pub trait Specification<T> {
    fn is_satisfied_by(&self, candidate: &T) -> bool;
}

pub struct LowBalanceFeeSpecification;

impl Specification<Account> for LowBalanceFeeSpecification {
    fn is_satisfied_by(&self, candidate: &Account) -> bool {
        candidate.balance < 100
    }
}
